import { readFile } from 'node:fs/promises';
import { test, expect } from '@playwright/test';
const ready=async page=>{await page.goto('/ckb-vm-js/');await expect(page.locator('#status')).toHaveText('Ready');};
const edit=async(page,kind,i=1)=>page.getByRole('button',{name:new RegExp(`^Edit ${kind} index ${i-1} · `)}).click();
const done=async page=>page.getByRole('button',{name:'Save',exact:true}).click();
test('overview and inspector edits preserve unknown data, round trips and recovery',async({page})=>{
 const errors=[];page.on('pageerror',e=>errors.push(e.message));await ready(page);
 await expect(page.getByLabel('Input index 0 capacity (CKB)',{exact:true})).toHaveCount(0);
 await edit(page,'input');await expect(page.getByLabel('Input index 0 capacity (CKB)',{exact:true})).toHaveValue('1000');await done(page);
 await page.getByRole('button',{name:'Add output',exact:true}).click();await edit(page,'output',2);
 let field=page.getByLabel('Output index 1 capacity (CKB)',{exact:true});await field.fill('61');await field.press('Tab');await done(page);
 let r=JSON.parse(await page.locator('#request').inputValue());expect(r.transaction.outputs).toHaveLength(2);expect(BigInt(r.transaction.outputs[1].capacity)).toBe(6100000000n);
 await page.locator('#advanced summary').click();r.extension={keep:['a',123]};await page.locator('#request').fill(JSON.stringify(r));
 await edit(page,'output');field=page.getByLabel('Output index 0 capacity (CKB)',{exact:true});await field.fill('500');await field.press('Tab');await done(page);
 expect(JSON.parse(await page.locator('#request').inputValue()).extension).toEqual({keep:['a',123]});
 await page.getByRole('button',{name:'Manage witnesses'}).click();await page.getByRole('button',{name:'Add witness',exact:true}).click();await expect(page.getByLabel('Witness index 0 (hex)',{exact:true})).toBeVisible();await done(page);
 await page.locator('#request').fill('{bad');await expect(page.locator('#workbench')).toContainText('Structured editor unavailable');await page.locator('#request').fill(JSON.stringify(r));
 await page.getByRole('button',{name:'Add input',exact:true}).click();const added=JSON.parse(await page.locator('#request').inputValue());expect(added.transaction.inputs).toHaveLength(2);expect(added.context.cells.at(-1).transaction_info).toBeNull();expect(errors).toEqual([]);
});
test('mobile overview fits within two screens, details retain invalid drafts and Escape returns focus',async({page})=>{
 await page.setViewportSize({width:390,height:844});await ready(page);
 expect(await page.evaluate(()=>document.documentElement.scrollWidth<=innerWidth)).toBe(true);
 expect(await page.locator('#run').evaluate(e=>e.getBoundingClientRect().bottom)).toBeLessThan(1688);
 await edit(page,'input');expect(await page.evaluate(()=>document.documentElement.scrollWidth<=innerWidth)).toBe(true);await page.keyboard.press('Escape');await expect(page.getByRole('button',{name:/^Edit input index 0 · /})).toBeFocused();
 await edit(page,'output');const field=page.getByLabel('Output index 0 capacity (CKB)',{exact:true});await field.fill('oops');await field.press('Tab');expect(await field.evaluate(e=>e.validity.valid)).toBe(false);await page.keyboard.press('Escape');await expect(page.locator('dialog')).not.toBeVisible();await edit(page,'output');const retry=page.getByLabel('Output index 0 capacity (CKB)',{exact:true});await retry.fill('999');await retry.press('Tab');await done(page);
 await page.locator('#advanced summary').click();let r=JSON.parse(await page.locator('#request').inputValue());r.transaction.inputs=[null];await page.locator('#request').fill(JSON.stringify(r));await expect(page.locator('#workbench')).toContainText('Needs attention');expect(JSON.parse(await page.locator('#request').inputValue()).transaction.inputs).toEqual([null]);
});
