test('header copy view preserves other references, supports back and focuses correctly',async({page})=>{
 await page.setViewportSize({width:390,height:700});await page.emulateMedia({reducedMotion:'reduce'});await ready(page);await page.locator('#advanced summary').click();const input=page.locator('#request');const request=JSON.parse(await input.inputValue());request.context.tip_header.hash='0x431643f20c2ddc95980bb2797c2a020d78cc05c849b70ab1a041c7e2768ec106';request.transaction.header_deps=[request.context.tip_header.hash,request.context.tip_header.hash];await input.fill(JSON.stringify(request));await page.locator('#advanced summary').click();const before=await input.inputValue();await page.getByRole('button',{name:'Manage header deps'}).click();await expect(page.locator('.header-list-row')).toHaveCount(2);await expect(page.locator('.header-list-row').first()).toContainText('block 100');await page.getByRole('button',{name:'Open header dep index 0'}).click();const edit=page.getByRole('button',{name:'Edit a copy'});await edit.click();await expect(page.getByRole('heading',{name:'Edit a copy · header dep index 0'})).toBeFocused();await expect(page.getByLabel('Computed header hash (read only)')).toHaveAttribute('readonly','');await page.getByLabel('Header Block number (RPC hex)').fill('0x65');await page.keyboard.press('Escape');await expect(edit).toBeFocused();expect(await input.inputValue()).toBe(before);await edit.click();await page.getByLabel('Header Block number (RPC hex)').fill('0x65');await page.getByLabel('Extension for this header').selectOption('none');await page.getByRole('button',{name:'Save header'}).click();await expect(page.locator('dialog')).not.toBeVisible();const after=JSON.parse(await input.inputValue());expect(after.context.tip_header).toEqual(request.context.tip_header);expect(after.transaction.header_deps[1]).toBe(request.transaction.header_deps[1]);expect(after.transaction.header_deps[0]).not.toBe(request.transaction.header_deps[0]);expect(after.context.headers.at(-1).hash).toBe(after.transaction.header_deps[0]);expect(await page.evaluate(()=>document.documentElement.scrollWidth<=innerWidth)).toBe(true);
});


